solution:
function removeDuplicates(nums) {
  if (nums.length === 0) return 0;
  let write = 1; // nums[0] is always kept
  for (let read = 1; read < nums.length; read++) {
    if (nums[read] !== nums[write - 1]) {
      nums[write] = nums[read];
      write++;
    }
  }
  return write;
}

tests.code:
const nums = [1, 1, 2];
const k = removeDuplicates(nums);
assertEqual(k, 2);
assertEqual(nums.slice(0, k), [1, 2]);

const nums = [70, 70, 82, 90, 90, 95];
const k = removeDuplicates(nums);
assertEqual(k, 4);
assertEqual(nums.slice(0, k), [70, 82, 90, 95]);

const nums = [0, 0, 1, 1, 1, 2, 2, 3, 3, 4];
const k = removeDuplicates(nums);
assertEqual(k, 5);
assertEqual(nums.slice(0, k), [0, 1, 2, 3, 4]);

const nums = [5, 5, 5, 5];
const k = removeDuplicates(nums);
assertEqual(k, 1);
assertEqual(nums.slice(0, k), [5]);

const a = [-3, -3, -1, 0, 0];
const ka = removeDuplicates(a);
assertEqual(a.slice(0, ka), [-3, -1, 0]);
const b = [1, 2, 3];
assertEqual(removeDuplicates(b), 3);
assertEqual(b, [1, 2, 3]);
